class Kus:
  tur = 'Kanatlı Hayvan' # Sınıf düzeyi özellik

  def __init__(self, isim):
    self.isim = isim # Nesne düzeyi özellik

k1 = Kus('Maviş')
print(k1.isim, k1.tur)

class Ogrenci:
  def __init__(self, isim, not_ortalamasi):
    self.isim = isim
    self.not_ortalamasi = not_ortalamasi

o1 = Ogrenci('Ayşe', 85)
print(o1.isim, o1.not_ortalamasi)

class Daire:
  def __init__(self, yaricap):
    self.yaricap = yaricap

  @property
  def alan(self):
    return 3.14 * self.yaricap ** 2

d = Daire(5)
print('Alan:', d.alan) # d.alan() yerine d.alan yazdık
